/* Griffin and Dragon wing beats: 16 frames each, drawn by Claude from the OpenArt pictures (the wings cut off at the shoulder and swung through a full beat) */
.mms-griffin{aspect-ratio:221/221}.fighter.blue .mms-griffin{background-image:url('myth/griffin_fly_blue.png')}.fighter.red .mms-griffin{background-image:url('myth/griffin_fly_red.png')}
.mms-dragon{aspect-ratio:395/313}.fighter.blue .mms-dragon{background-image:url('myth/dragon_fly_blue.png')}.fighter.red .mms-dragon{background-image:url('myth/dragon_fly_red.png')}
